console.log('\n=== Edge cases ===');
// Test 6: Multiple prerelease tags
console.log('6. Multiple tags (alpha in list):', satisfies('1.3.0-alpha.1', '^1.2.0', { prereleaseTags: ['rc', 'alpha'] }), '(expected: true)');

// Test 7: Multiple prerelease tags, beta not in list
console.log('7. Multiple tags (beta not in list):', satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['rc', 'alpha'] }), '(expected: false)');

// Test 8: Numeric prerelease (should be converted to string)
console.log('8. Numeric prerelease identifier:', satisfies('1.3.0-1.1', '^1.2.0', { prereleaseTags: ['1'] }), '(expected: true)');

// Test 9: Empty prereleaseTags array
console.log('9. Empty prereleaseTags:', satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: [] }), '(expected: false)');

// Test 10: Range matches based on original prerelease behavior (not prereleaseTags)
console.log('10. Range with prerelease, no prereleaseTags:', satisfies('1.2.3-rc.1', '>=1.2.3-rc.0'), '(expected: true)');

console.log('\n=== Functions ===');
// Test maxSatisfying
const versions = ['1.3.0-rc.1', '1.3.0-beta.1', '1.2.5', '1.3.0', '2.0.0-rc.1'];
console.log('11. maxSatisfying with prereleaseTags:', maxSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }), '(expected: 1.3.0)');

// Test minSatisfying
console.log('12. minSatisfying with prereleaseTags:', minSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }), '(expected: 1.2.5)');

// Test Range.test
const range = new Range('^1.2.0', { prereleaseTags: ['rc'] });
console.log('13. Range.test with prereleaseTags:', range.test('1.3.0-rc.1'), '(expected: true)');
"

